mapper.update:
UPDATE purchase_orders
   SET supplier_id = #{supplierId},
       total_amount = #{totalAmount},
       updated_at = now(),
       updated_by = #{updatedBy}
 WHERE id = #{id}

UPDATE purchase_orders
   SET status = 'APPROVED', approved_at = #{at}, approved_by = #{by}, updated_at = now()
 WHERE id = #{id}

UPDATE purchase_orders
   SET status = 'COMPLETED', completed_at = #{at}, completed_by = #{by}, updated_at = now()
 WHERE id = #{id}

UPDATE purchase_orders
   SET status = 'CANCELLED', cancelled_at = #{at}, cancelled_by = #{by}, updated_at = now()
 WHERE id = #{id}
